mapper.insert:
INSERT INTO bike_inventory_lock(lock_no,agent_id,customer_id,sku_id,product_model_id,scope_type,lock_qty,converted_qty,expire_time,created_by,status,remark)
SELECT #{lockNo},p.agent_id,p.customer_id,sku.id,sku.model_id,'SKU',#{quantity},#{quantity},NOW(3),#{operatorId},'CONVERTED','PI按合同收款后建立订单库存占用'
FROM bike_pi p JOIN bike_production_sku sku ON sku.id=#{skuId} WHERE p.id=#{piId}
